refentry.refsect1:
&reftitle.description;
stringarraystr_replace arraystringsearch arraystringreplace stringarraysubject intcount&null;
Questa funzione restituisce una stringa o un array con tutte le occorrenze di search in subject sostituite con il valore replace indicato.
Per sostituire del testo in base a un pattern invece che a una stringa fissa, si usi preg_replace.

  &reftitle.examples;



    Esempi di base di str_replace


<?php
// Produce: <body text='black'>
$bodytag = str_replace("%body%", "black", "<body text='%body%'>");
echo $bodytag, PHP_EOL;

// Produce: C Mnd dl PHP
$vowels = array("a", "e", "i", "o", "u", "A", "E", "I", "O", "U");
$onlyconsonants = str_replace($vowels, "", "Ciao Mondo del PHP");
echo $onlyconsonants, PHP_EOL;

// Produce: Si dovrebbero mangiare pizza, birra e gelato ogni giorno.
$phrase  = "Si dovrebbero mangiare frutta, verdura e fibre ogni giorno.";
$healthy = array("frutta", "verdura", "fibre");
$yummy   = array("pizza", "birra", "gelato");

$newphrase = str_replace($healthy, $yummy, $phrase);
echo $newphrase, PHP_EOL;

// Produce: 2
$str = str_replace("ll", "", "che bella palla!", $count);
echo $count, PHP_EOL;
?>







    Esempi di potenziali insidie di str_replace


<?php
// Ordine di sostituzione
$str     = "Riga 1\nRiga 2\rRiga 3\r\nRiga 4\n";
$order   = array("\r\n", "\n", "\r");
$replace = '<br />';

// Elabora prima i \r\n in modo che non vengano convertiti due volte.
$newstr = str_replace($order, $replace, $str);
echo $newstr, PHP_EOL;

// Restituisce F perché A viene sostituita con B, poi B viene sostituita con C, e così via...
// Alla fine E viene sostituita con F, perché le sostituzioni avvengono da sinistra a destra.
$search  = array('A', 'B', 'C', 'D', 'E');
$replace = array('B', 'C', 'D', 'E', 'F');
$subject = 'A';
echo str_replace($search, $replace, $subject), PHP_EOL;

// Restituisce: perarancia arancia
// Per lo stesso motivo indicato sopra
$letters = array('p', 'a');
$fruit   = array('pera', 'arancia');
$text    = 'p a';
$output  = str_replace($letters, $fruit, $text);
echo $output, PHP_EOL;
?>
